// sort: 1,000,000 numbers generated by a deterministic xorshift32 PRNG,
// sorted with an explicit comparator (a - b).
let state: u32 = 2463534242;
function nextRand(): u32 {
  state ^= state << 13;
  state ^= state >>> 17;
  state ^= state << 5;
  return state >>> 0;
}

const N: i32 = 1000000;
const arr: number[] = [];
for (let i: i32 = 0; i < N; i++) arr.push(nextRand() % 1000000);

arr.sort((a: number, b: number) => a - b);

let checksum: number = 0;
for (let i: i32 = 0; i < N; i += 10007) checksum += arr[i];
checksum += arr[0] + arr[N - 1];

console.log(checksum);
